<style>
.ss-page{font-family:Inter,Arial,sans-serif;color:#25313C}.ss-head{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:20px}.ss-head h1{font-size:23px;font-weight:700;color:#123B5D;margin:0 0 6px}.ss-sub{font-size:13px;color:#64748B}.ss-actions{display:flex;gap:9px;flex-wrap:wrap;justify-content:flex-end}.ss-btn{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 15px;border:1px solid #CBD5E1;border-radius:9px;background:#fff;color:#123B5D;text-decoration:none;font-size:13px;font-weight:600;cursor:pointer}.ss-btn.primary{background:#123B5D;border-color:#123B5D;color:#fff}.ss-btn.danger{color:#DC2626}.ss-panel{background:#fff;border:1px solid #CBD5E1;border-radius:15px;padding:18px;margin-bottom:18px}.ss-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.ss-card{background:#fff;border:1px solid #CBD5E1;border-radius:14px;padding:18px;text-decoration:none;color:inherit}.ss-card h3{margin:0 0 7px;color:#123B5D;font-size:16px}.ss-card p{margin:0 0 15px;color:#64748B;font-size:12px;min-height:34px}.ss-kpis{display:flex;gap:22px}.ss-kpi b{display:block;font-size:25px;color:#123B5D}.ss-kpi span{font-size:11px;color:#64748B}.ss-table{width:100%;border-collapse:collapse}.ss-table th{background:#F8FAFC;color:#64748B;font-size:11px;text-align:left;padding:12px;border-bottom:1px solid #CBD5E1}.ss-table td{padding:13px 12px;border-bottom:1px solid #E2E8F0;font-size:13px;vertical-align:middle}.ss-field{display:flex;flex-direction:column;gap:7px}.ss-field label{font-size:12px;font-weight:650;color:#334155}.ss-field input,.ss-field select,.ss-field textarea{width:100%;border:1px solid #CBD5E1;border-radius:9px;padding:11px 12px;font:13px Inter,Arial,sans-serif;color:#25313C;background:#fff}.ss-field textarea{min-height:110px;resize:vertical}.ss-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.ss-full{grid-column:1/-1}.ss-muted{color:#64748B;font-size:12px}.ss-badge{display:inline-block;padding:5px 9px;border-radius:20px;background:#EFF6FF;color:#1D4ED8;font-size:11px;font-weight:700}.ss-error{color:#DC2626;font-size:12px}@media(max-width:900px){.ss-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.ss-head{flex-direction:column}.ss-actions{justify-content:flex-start}.ss-grid,.ss-form{grid-template-columns:1fr}.ss-full{grid-column:auto}.ss-panel{overflow-x:auto}}
</style>
